import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"真实工程实践","description":"从 Vue 3 笔记应用、Express 服务端，以及 PHP/Yaf、Vue 2、移动 H5 和微信小程序项目中整理出的可复用开发经验。","frontmatter":{"title":"真实工程实践","description":"从 Vue 3 笔记应用、Express 服务端，以及 PHP/Yaf、Vue 2、移动 H5 和微信小程序项目中整理出的可复用开发经验。"},"headers":[],"relativePath":"practice/index.md","filePath":"practice/index.md","lastUpdated":1792634344000}'),c={name:"practice/index.md"};function d(o,a,l,h,n,p){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="真实工程实践" tabindex="-1">真实工程实践 <a class="header-anchor" href="#真实工程实践" aria-label="Permalink to &quot;真实工程实践&quot;">​</a></h1><p>这里收录两组真实项目经验：一组来自 Vue 3、Express 与 MySQL 构建的笔记应用；另一组来自 PHP/Yaf 服务端支撑 PC 管理后台、移动 H5 和微信小程序的多端系统。</p><p>文章不会按源码目录逐个介绍，而是挑开发中反复出现的问题，用短流程图、简化项目代码和检查清单讲清楚。</p><blockquote><p>代码保留了真实项目中的工程模式，但已经删除生产地址、凭据、客户数据、内部业务名称和特殊常量。</p></blockquote><h2 id="第一次来-建议这样读" tabindex="-1">第一次来，建议这样读 <a class="header-anchor" href="#第一次来-建议这样读" aria-label="Permalink to &quot;第一次来，建议这样读&quot;">​</a></h2><p>如果你正在做 Vue 3 编辑器、知识库或个人工具，从<a href="/practice/notes-architecture">笔记应用：从编辑器到可靠保存</a>开始。</p><p>如果你在维护多端业务系统，可以按下面的顺序阅读：</p><ol><li><a href="/practice/full-stack-system-map">一次需求到底要改哪里</a>：先看懂多端系统的完整请求链。</li><li><a href="/practice/cross-client-api-contract">PC、H5 和小程序怎样统一 API</a>：统一成功、失败、登录与重复提交。</li><li><a href="/practice/legacy-modernization-roadmap">旧系统怎样一步步改</a>：不停止业务，也不做高风险推倒重来。</li></ol><p>这三篇建立整体视角，后面的文章可以按当前问题直接选择。</p><h2 id="笔记应用-vue-3-与-express-全栈实践" tabindex="-1">笔记应用：Vue 3 与 Express 全栈实践 <a class="header-anchor" href="#笔记应用-vue-3-与-express-全栈实践" aria-label="Permalink to &quot;笔记应用：Vue 3 与 Express 全栈实践&quot;">​</a></h2><p>这一组围绕“用户写下的内容怎样可靠保存”展开，取材于 PC 客户端、共享数据层和独立服务端的实际实现。已实现的行为、设计取舍和后续建议分别说明。</p><table tabindex="0"><thead><tr><th>文章</th><th>解决的问题</th></tr></thead><tbody><tr><td><a href="/practice/notes-architecture">从编辑器到可靠保存</a></td><td>共享数据层、页面状态、编辑会话与服务端各自负责什么</td></tr><tr><td><a href="/practice/notes-save-lifecycle">编辑会话与本地草稿</a></td><td>保存期间继续输入、切换文档、恢复草稿和账号隔离</td></tr><tr><td><a href="/practice/notes-sync-consistency">快照同步与并发冲突</a></td><td>多窗口覆盖、目录移动、旧快照复活已删除内容</td></tr><tr><td><a href="/practice/notes-rich-text-assets">富文本与附件生命周期</a></td><td>Markdown 粘贴、HTML 存储、自定义节点和私有附件</td></tr><tr><td><a href="/practice/notes-ai-editing">AI 编辑的可靠性边界</a></td><td>长任务取消、容量单位、完整输出和预览采纳</td></tr><tr><td><a href="/practice/notes-release-recovery">懒加载与发布恢复</a></td><td>旧标签页请求不到页面资源，以及保护编辑内容的恢复流程</td></tr></tbody></table><h2 id="服务端开发" tabindex="-1">服务端开发 <a class="header-anchor" href="#服务端开发" aria-label="Permalink to &quot;服务端开发&quot;">​</a></h2><h3 id="php-9-2-分漏洞怎么处理" tabindex="-1"><a href="/practice/php-critical-vulnerability-response">PHP 9.2 分漏洞怎么处理</a> <a class="header-anchor" href="#php-9-2-分漏洞怎么处理" aria-label="Permalink to &quot;[PHP 9.2 分漏洞怎么处理](/practice/php-critical-vulnerability-response)&quot;">​</a></h3><p>根据 PHP2Shell 官方公告和 Windows/Yaf 项目的静态检查，说明运行时盘点、临时缓解、补丁回补和兼容迁移的边界，并给出验证与回滚顺序。</p><h3 id="yaf-多应用项目怎样整理" tabindex="-1"><a href="/practice/yaf-multi-app-architecture">Yaf 多应用项目怎样整理</a> <a class="header-anchor" href="#yaf-多应用项目怎样整理" aria-label="Permalink to &quot;[Yaf 多应用项目怎样整理](/practice/yaf-multi-app-architecture)&quot;">​</a></h3><p>适合遇到多个入口、多个应用目录、共享模型和公共库的 PHP 项目。重点说明入口、控制器、业务服务、配置和共享代码各自负责什么。</p><h3 id="事务、幂等和补偿怎么配合" tabindex="-1"><a href="/practice/transactional-business-workflow">事务、幂等和补偿怎么配合</a> <a class="header-anchor" href="#事务、幂等和补偿怎么配合" aria-label="Permalink to &quot;[事务、幂等和补偿怎么配合](/practice/transactional-business-workflow)&quot;">​</a></h3><p>适合订单、库存、支付、预约等不能重复执行的写操作。用白话解释数据库事务、重复请求、外部调用超时和失败恢复。</p><h2 id="前端与小程序" tabindex="-1">前端与小程序 <a class="header-anchor" href="#前端与小程序" aria-label="Permalink to &quot;前端与小程序&quot;">​</a></h2><h3 id="vue-2-多端项目怎样继续维护" tabindex="-1"><a href="/practice/vue2-multi-terminal-engineering">Vue 2 多端项目怎样继续维护</a> <a class="header-anchor" href="#vue-2-多端项目怎样继续维护" aria-label="Permalink to &quot;[Vue 2 多端项目怎样继续维护](/practice/vue2-multi-terminal-engineering)&quot;">​</a></h3><p>对比 PC 后台和移动 H5 的路由、请求层、Vuex 与组件库使用方式，给出不用一次重写的整理方法。</p><h3 id="微信内-h5-为什么总有-偶现问题" tabindex="-1"><a href="/practice/mobile-h5-reliability">微信内 H5 为什么总有“偶现问题”</a> <a class="header-anchor" href="#微信内-h5-为什么总有-偶现问题" aria-label="Permalink to &quot;[微信内 H5 为什么总有“偶现问题”](/practice/mobile-h5-reliability)&quot;">​</a></h3><p>说明登录回跳、页面恢复、弱网、重复点击和宿主 SDK 为什么容易互相影响，以及怎样用简单状态机解决。</p><h3 id="原生小程序怎样组织才不乱" tabindex="-1"><a href="/practice/native-mini-program-architecture">原生小程序怎样组织才不乱</a> <a class="header-anchor" href="#原生小程序怎样组织才不乱" aria-label="Permalink to &quot;[原生小程序怎样组织才不乱](/practice/native-mini-program-architecture)&quot;">​</a></h3><p>从 <code>App</code>、<code>Page</code>、<code>Component</code>、<code>request</code> 和 <code>session</code> 开始，讲清登录、授权、分包、性能和联调。</p><h2 id="分享经验但不泄露项目" tabindex="-1">分享经验但不泄露项目 <a class="header-anchor" href="#分享经验但不泄露项目" aria-label="Permalink to &quot;分享经验但不泄露项目&quot;">​</a></h2><h3 id="私有项目怎么写成公开技术文章" tabindex="-1"><a href="/practice/public-writing-from-private-code">私有项目怎么写成公开技术文章</a> <a class="header-anchor" href="#私有项目怎么写成公开技术文章" aria-label="Permalink to &quot;[私有项目怎么写成公开技术文章](/practice/public-writing-from-private-code)&quot;">​</a></h3><p>介绍怎样挑选代码、重写示例、合成数据、扫描构建产物，并区分“项目现状”和“推荐方案”。</p><h2 id="按问题快速选择" tabindex="-1">按问题快速选择 <a class="header-anchor" href="#按问题快速选择" aria-label="Permalink to &quot;按问题快速选择&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你现在遇到的问题</th><th>建议阅读</th></tr></thead><tbody><tr><td>保存成功后，请求期间的新输入却丢了</td><td><a href="/practice/notes-save-lifecycle">编辑会话与本地草稿</a></td></tr><tr><td>多设备互相覆盖，删除内容又被同步回来</td><td><a href="/practice/notes-sync-consistency">快照同步与并发冲突</a></td></tr><tr><td>AI 生成后怎样安全采纳并保存</td><td><a href="/practice/notes-ai-editing">AI 编辑的可靠性边界</a></td></tr><tr><td>发布后，已打开的页面无法切换路由</td><td><a href="/practice/notes-release-recovery">懒加载与发布恢复</a></td></tr><tr><td>一个需求不知道会影响哪些仓库</td><td><a href="/practice/full-stack-system-map">多端系统全景图</a></td></tr><tr><td>三个客户端对同一接口判断不一样</td><td><a href="/practice/cross-client-api-contract">跨端 API 契约</a></td></tr><tr><td>Yaf 控制器和公共库越来越大</td><td><a href="/practice/yaf-multi-app-architecture">Yaf 多应用架构</a></td></tr><tr><td>PHP 爆出严重漏洞，旧项目又不能直接升级</td><td><a href="/practice/php-critical-vulnerability-response">PHP 漏洞处置与升级</a></td></tr><tr><td>写操作偶尔重复或状态不一致</td><td><a href="/practice/transactional-business-workflow">高一致性业务工作流</a></td></tr><tr><td>Vue 2 路由、全局方法和 UI 库混在一起</td><td><a href="/practice/vue2-multi-terminal-engineering">Vue 2 多端工程治理</a></td></tr><tr><td>H5 登录后回不来或重复弹窗</td><td><a href="/practice/mobile-h5-reliability">移动 H5 可靠性</a></td></tr><tr><td>小程序登录、定位和页面生命周期互相打架</td><td><a href="/practice/native-mini-program-architecture">原生小程序架构</a></td></tr><tr><td>想升级旧技术栈又担心风险</td><td><a href="/practice/legacy-modernization-roadmap">渐进式治理路线</a></td></tr><tr><td>想分享项目经验但担心泄密</td><td><a href="/practice/public-writing-from-private-code">私有源码公开写作</a></td></tr></tbody></table><h2 id="每篇文章都遵守的写法" tabindex="-1">每篇文章都遵守的写法 <a class="header-anchor" href="#每篇文章都遵守的写法" aria-label="Permalink to &quot;每篇文章都遵守的写法&quot;">​</a></h2><ul><li>先说明问题，不先堆术语；</li><li>一次只解释一条主流程；</li><li>代码片段尽量短，并说明它解决什么；</li><li>同时写成功路径和失败路径；</li><li>最后给出可以直接复制的检查清单。</li></ul><p>如果只准备读一篇，从<a href="/practice/full-stack-system-map">一次需求到底要改哪里</a>开始。</p>',34)])])}const f=t(c,[["render",d]]);export{u as __pageData,f as default};
